CREATE VIEW v64694 AS SELECT ADDTIME(x1.v63835, 'POINT(362642540 104419188)'), ST_ASTEXT(ST_GEOMFROMTEXT('POLYGON((0 0, 50 45, 40 50, 0 0))')), YEARWEEK(), SUBSTRING_INDEX('aaaaaaaaa1', 'aaaa', 1), CONV((1 << 48) - 8, 10, 16), EXTRACTVALUE(@xml, '/a/b[2]'), ADDTIME(CAST(x1.x1 AS CHAR(3)), CAST('00:00:00.000000' AS TIME)) FROM v63903 AS x1